import React, { useMemo } from "react";
import { AbsoluteFill, random, useCurrentFrame } from "remotion";
import { Camera, ParallaxLayer, useCamera } from "../camera/Camera";
import { Stage } from "../stage/Stage";
import { SceneLighting } from "../stage/SceneLighting";
import { PaperBackground } from "../paper/PaperBackground";
import { GoldFrame } from "../ornaments/GoldFrame";
import { Cloud, SkyGradient, SunOnWire } from "../sets/Sky";
import { FloralArchFrame, FlowerWall, FlowerWallDefs, LowStage } from "../sets/WeddingDayFloral";
import { people, wardrobe } from "../characters/cast";
import type { Pose } from "../characters/types";
import { Figure, Gate, SVG, fig, handAt, lerpPt, qPt, reachPose, toScene, type Fig, type Pt } from "../props/WeddingDayKit";
import { Varmala } from "../props/WeddingDayGarland";
import { FlowerHeap } from "../props/WeddingDayDecor";
import { Flower, Leaf, Petal } from "../props/Florals";
import { FallingPetals } from "../kit/Particles";
import { EventTitle } from "../kit/EventTitle";
import { EASE, prog, wave } from "../kit/motion";
import { palette } from "../theme/palette";
import type { SceneProps } from "./types";
import { bi, whenBi } from "../data/i18n";

const FEET = 1478;
const R = fig(people.rishabh, 436, FEET, 800);
const N = fig(people.nandita, 648, FEET, 800);
const WALL_TOP = 560;
const ARCH = { x: 300, w: 480, spring: 930, apex: 660 };

type Transfer = { giver: Fig; receiver: Fig; start: number; seed: string };

/** Where a garland is at `frame`: its two hold points and sag, plus the giver's hand targets. */
const garlandAt = (g: Transfer, frame: number) => {
  const handsHold = [toScene(g.giver, 136, 540), toScene(g.giver, 264, 540)] as Pt[];
  const shoulders = [toScene(g.receiver, 146, 250), toScene(g.receiver, 254, 250)] as Pt[];
  const u = prog(frame, g.start, 30, EASE.inOut);
  // lift → carry over the receiver's head (loop opened wide) → lower onto the shoulders
  const headTop = toScene(g.receiver, 200, -70)[1];
  const lift = prog(u, 0, 0.62, EASE.inOut);
  const lower = prog(u, 0.62, 0.38, EASE.inOut);
  const pts = [0, 1].map((i) => {
    const p0 = handsHold[i];
    const p2 = shoulders[i];
    const over: Pt = [p2[0] + (i === 0 ? -62 : 62), headTop];
    const c: Pt = [(p0[0] + over[0]) / 2, Math.min(p0[1], over[1]) - 40];
    const up = qPt(p0, c, over, lift);
    return lower > 0 ? lerpPt(over, p2, lower) : up;
  });
  const drapeSag = 250 * (g.receiver.h / 800);
  const land = frame - (g.start + 30);
  const settle = land > 0 ? Math.sin(land / 4) * Math.exp(-land / 10) * 0.07 : 0;
  const sag = lower > 0 ? 40 + (drapeSag - 40) * lower : 190 - 150 * lift;
  // giver's hands follow the garland, then let go and come home
  const release = prog(frame, g.start + 25, 16, EASE.inOut);
  return { a: pts[0], b: pts[1], sag: sag * (1 + settle), u, release };
};

/**
 * Jaimaal — the exchange of garlands on a low stage before a wall of roses, jasmine and marigolds.
 * Nandita garlands Rishabh, then he garlands her; a burst of petals hangs in slow motion.
 */
export const JaimaalScene: React.FC<SceneProps> = ({ inv, dur }) => {
  const frame = useCurrentFrame();
  const cam = useCamera([
    { frame: 0, scale: 1.0, y: 0 },
    { frame: dur - 4, scale: 1.08, y: 40, ease: EASE.inOut },
  ]);

  const g1: Transfer = { giver: N, receiver: R, start: 30, seed: "vm-n" };
  const g2: Transfer = { giver: R, receiver: N, start: 60, seed: "vm-r" };
  const s1 = garlandAt(g1, frame);
  const s2 = garlandAt(g2, frame);

  // hands: hold own garland at the chest → follow it → release to a soft namaste-low clasp
  const restN: Pt[] = [handAt(N, "l", 16, -64), handAt(N, "r", -16, 64)];
  const restR: Pt[] = [handAt(R, "l", 14, -58), handAt(R, "r", -14, 58)];
  const handsFor = (s: ReturnType<typeof garlandAt>, rest: Pt[]): Pt[] => [lerpPt(s.a, rest[0], s.release), lerpPt(s.b, rest[1], s.release)];
  const nHands = handsFor(s1, restN);
  const rHands = handsFor(s2, restR);
  const nPose: Partial<Pose> = { ...reachPose(N, nHands[0], nHands[1], -1, 1), headTilt: -4 - 6 * Math.sin(prog(frame, 66, 30) * Math.PI) + wave(frame, 120) * 0.6 };
  const rPose: Partial<Pose> = { ...reachPose(R, rHands[0], rHands[1], -1, 1), headTilt: 4 + 6 * Math.sin(prog(frame, 36, 30) * Math.PI) + wave(frame, 130, 1) * 0.6 };
  const rFront = frame >= 66; // whoever reaches is drawn in front

  // petal burst in slow motion at the second garland's landing
  const burstAt = 88;
  const tb = frame - burstAt;
  const slow = tb <= 0 ? 0 : tb < 6 ? tb : 6 + (tb - 6) * 0.3; // quick pop, then slow-motion drift
  const origin: Pt = [542, 610];
  const burst = useMemo(
    () =>
      new Array(46).fill(0).map((_, i) => {
        const a = -Math.PI / 2 + (random(`jb-a${i}`) - 0.5) * Math.PI * 0.95;
        const v = 9 + random(`jb-v${i}`) * 12;
        return {
          vx: Math.cos(a) * v,
          vy: Math.sin(a) * v,
          spin: (random(`jb-s${i}`) - 0.5) * 20,
          s: 0.9 + random(`jb-z${i}`) * 0.9,
          c: [palette.rose, palette.marigold, palette.roseLight, "#FBF1DE", palette.turmeric][i % 5],
        };
      }),
    [],
  );

  const item = inv.events.weddingDay.items.find((i) => i.id === "jaimaal");
  const titleStart = Math.min(44, dur - 110 - 52);

  const couple = [
    <Figure key="r" f={R} person={people.rishabh} outfit={wardrobe.rishabh.wedding} pose={rPose} sehra={0} />,
    <Figure key="n" f={N} person={people.nandita} outfit={wardrobe.nandita.wedding} pose={nPose} />,
  ];

  return (
    <Stage background="#F6E8CC">
      <Camera state={cam}>
        {/* SKY — high noon, ivory-gold; the sun at the top of its wire */}
        <ParallaxLayer depth={0.1} blurStrength={0}>
          <SVG>
            <SkyGradient id="jaimaal-sky" top="#F2D9A6" mid="#FAEDD2" bottom="#FCF4E2" />
            <Cloud x={80} y={300} w={240} fill="#FDF3DE" line={palette.goldLight} />
            <Cloud x={760} y={420} w={220} fill="#FDF3DE" />
            <SunOnWire t={0.5} drop={60} />
          </SVG>
          <PaperBackground stock="cream" seed="jaimaal-sky" fibres={22} textureOnly />
        </ParallaxLayer>

        {/* DECORATION — flower wall with the jasmine arch, floral arch frames */}
        <ParallaxLayer depth={0.5} blurStrength={4}>
          <SVG>
            <FlowerWallDefs id="jaimaal-wall" tint={0.12} />
            <FlowerWall patternId="jaimaal-wall" x0={-60} x1={1140} top={WALL_TOP} base={1500} arch={ARCH} sway={wave(frame, 150) * 5} />
          </SVG>
        </ParallaxLayer>
        <ParallaxLayer depth={0.75} blurStrength={4}>
          <SVG>
            <FloralArchFrame x0={60} x1={250} base={1500} top={700} seed="jm-al" r={24} />
            <FloralArchFrame x0={830} x1={1020} base={1500} top={700} seed="jm-ar" r={24} tones={["ivory", "rose", "orange", "ivory", "rose"]} />
          </SVG>
        </ParallaxLayer>

        {/* STAGE + COUPLE */}
        <ParallaxLayer depth={1} blurStrength={4}>
          <SVG>
            <rect x={-100} y={1540} width={1300} height={500} fill="#EFE2C8" />
            {[1640, 1740, 1860].map((y) => (
              <rect key={y} x={-100} y={y} width={1300} height={1} fill={palette.gold} opacity={0.3} />
            ))}
            <LowStage x0={150} x1={930} y={FEET - 8} h={62} />
            <ellipse cx={540} cy={FEET} rx={260} ry={14} fill={palette.ink} opacity={0.1} />
          </SVG>
          {rFront ? [couple[1], couple[0]] : couple}
          <SVG>
            {/* the garland she gives rides on top; his garland too */}
            <Varmala a={s1.a} b={s1.b} sag={s1.sag} r={12} seed={g1.seed} swing={Math.sin(frame / 18) * 3 * (1 - s1.u)} />
            <Varmala a={s2.a} b={s2.b} sag={s2.sag} r={12} seed={g2.seed} swing={Math.sin(frame / 18 + 1) * 3 * (1 - s2.u)} tones={["ivory", "rose", "orange", "ivory", "rose", "yellow"]} />
            <FlowerHeap x={540} y={FEET + 4} w={760} r={15} seed="jm-heap" rows={1} />
            {[150, 930].map((x, i) => (
              <g key={x}>
                <path d={`M${x - 30} ${FEET - 8} C${x - 42} ${FEET - 60} ${x - 30} ${FEET - 90} ${x} ${FEET - 96} C${x + 30} ${FEET - 90} ${x + 42} ${FEET - 60} ${x + 30} ${FEET - 8} Z`} fill={palette.brass} />
                <path d={`M${x - 30} ${FEET - 60} L${x + 30} ${FEET - 60}`} stroke={palette.goldPale} strokeWidth={0} />
                <rect x={x - 36} y={FEET - 64} width={72} height={3} fill={palette.goldPale} />
                <FlowerHeap x={x} y={FEET - 96} w={110} r={16} seed={`jm-urn${i}`} rows={2} />
              </g>
            ))}
            {[210, 380, 700, 860].map((x, i) => (
              <Petal key={x} x={x} y={1590 + (i % 2) * 20} rot={i * 50} s={1.2} color={i % 2 ? palette.rose : palette.marigold} />
            ))}
          </SVG>
        </ParallaxLayer>

        {/* PETAL BURST — slow motion */}
        {tb > 0 ? (
          <ParallaxLayer depth={1.05} blurStrength={0}>
            <SVG>
              {burst.map((p, i) => {
                const tau = 14;
                const d = tau * (1 - Math.exp(-slow / tau));
                const x = origin[0] + p.vx * d + Math.sin((slow + i * 7) / 9) * 10;
                const y = origin[1] + p.vy * d + 0.04 * slow * slow;
                const fade = Math.min(1, tb / 3) * (1 - prog(frame, dur - 40, 30));
                return (
                  <g key={i} opacity={fade} transform={`translate(${x} ${y}) rotate(${slow * p.spin}) scale(${p.s} ${p.s * (0.45 + 0.55 * Math.abs(Math.cos(slow / 7 + i)))})`}>
                    <path d="M0 0 C6 -8 16 -8 18 0 C16 7 6 8 0 0 Z" fill={p.c} />
                  </g>
                );
              })}
            </SVG>
          </ParallaxLayer>
        ) : null}

        {/* FOREGROUND — out-of-focus roses at the corners */}
        <ParallaxLayer depth={1.4} blurStrength={0} style={{ filter: "blur(7px)" }}>
          <SVG>
            <Leaf x={-30} y={140} rot={20} s={4} color={palette.greenDeep} />
            <Flower x={40} y={110} r={60} tone="rose" />
            <Flower x={130} y={60} r={42} tone="ivory" />
            <Flower x={1040} y={80} r={56} tone="orange" />
            <Leaf x={1000} y={170} rot={150} s={3.6} />
            <Flower x={1050} y={1860} r={58} tone="rose" />
            <Flower x={960} y={1905} r={36} tone="ivory" />
            <Leaf x={-10} y={1880} rot={-20} s={3.4} color={palette.greenDeep} />
            <Flower x={40} y={1880} r={44} tone="orange" />
          </SVG>
        </ParallaxLayer>
        <FallingPetals count={12} seed="jaimaal-petals" speed={0.45} start={burstAt - 200} size={1.1} opacity={0.8} />
      </Camera>

      <SceneLighting
        warmth={0.35}
        keyX={50}
        keyY={18}
        spots={[
          { x: 50, y: 40, r: 36, color: "#FFF3D6", intensity: 0.2 + 0.25 * Math.sin(prog(frame, burstAt - 4, 40) * Math.PI) },
          { x: 50, y: 20, r: 30, color: "#FFE9B8", intensity: 0.18 },
        ]}
        vignette={0.4}
      />

      <AbsoluteFill>
        <Gate from={titleStart}>
          <EventTitle start={titleStart} kicker="The Exchange of Garlands" title={item?.title ?? "Jaimaal"} lines={[whenBi(inv.events.weddingDay.date, item?.time), bi(inv.events.weddingDay.venue)]} top={1628} titleSize={98} />
        </Gate>
      </AbsoluteFill>

      <GoldFrame />
    </Stage>
  );
};
